usage.code:
import { OptionWheel } from "solen-design/react";

const genres = ["Ambient", "House", "Techno", "Jazz", "Lo-Fi", "Synthwave"];

<div style={{ height: 420 }}>
  <OptionWheel
    items={genres}
    defaultSelected={2}
    side="left"
    fontSize={3}
    spacing={1.4}
    curve={1}
    tilt={6}
    blur={2}
    fade={0.25}
    minOpacity={0.05}
    smoothing={200}
    inset={80}
    loop={false}
    draggable={true}
    textColor="#a6a6a6"
    activeColor="#ffffff"
    onChange={(index, item) => console.log(index, item)}
  />
</div>
